#include <bits/stdc++.h>
using namespace std;
#define rep(i, n) for(int i = 0; i < n; ++i)

int main(void){
	int n,sz;
	cin>>n;
	vector<int>a(n),c(n);
	vector<vector<int> >b(n);
	int ans=n;
	rep(i,n){
		cin>>a[i];
		a[i]--,c[a[i]]++;
	}
	rep(i,n)if(c[i]==0){
		ans--;
		b[0].push_back(i);
	}
	rep(i,n-1){
		sz=b[i].size();
		if(sz==0)break;
		rep(j,sz){
			c[a[b[i][j]]]--;
			if(c[a[b[i][j]]]==0)ans--,b[i+1].push_back(a[b[i][j]]);
		}
	}
    cout<<ans<<endl;
	return 0;
}

#include <iostream>
#include <atcoder/scc>

using namespace std;
using namespace atcoder;

int main(){
    int N;
    cin >> N;
    scc_graph g(N);
    int ans = 0;
    for(int i = 0; i < N; ++i){
        int A;
        cin >> A, --A;
        g.add_edge(i, A);
        if(i == A){
            ++ans;
        }
    }
    for(auto c: g.scc()){
        if(c.size() >= 2){
            ans += c.size();
        }
    }
    cout << ans << endl;
}
